<script>
(function(){
var form=document.getElementById('regForm');
var STORE_KEY='registered_users';
var successBanner=document.getElementById('successBanner');
var alertSummary=document.getElementById('alertSummary');

function getUsers(){try{return JSON.parse(localStorage.getItem(STORE_KEY))||[]}catch(e){return[]}}
function saveUsers(u){localStorage.setItem(STORE_KEY,JSON.stringify(u))}
function showError(id,msg){var el=document.getElementById(id);if(msg){el.textContent=msg;el.classList.add('show')}else{el.textContent='';el.classList.remove('show')}}
function setInvalid(inputId,invalid){var el=document.getElementById(inputId);if(invalid){el.setAttribute('aria-invalid','true')}else{el.setAttribute('aria-invalid','false')}}
function clearInvalid(inputId){var el=document.getElementById(inputId);el.removeAttribute('aria-invalid')}
function showSummary(msg){alertSummary.textContent=msg;alertSummary.classList.add('show')}
function hideSummary(){alertSummary.textContent='';alertSummary.classList.remove('show')}

function validateUsername(){
var raw=document.getElementById('username').value;
var v=raw.trim();
if(!v){showError('usernameErr','Username is required.');setInvalid('username',true);return false}
if(v.length<3){showError('usernameErr','Username must be at least 3 characters.');setInvalid('username',true);return false}
if(v.length>20){showError('usernameErr','Username must be 20 characters or fewer.');setInvalid('username',true);return false}
if(!/^[a-zA-Z]/.test(v)){showError('usernameErr','Username must start with a letter.');setInvalid('username',true);return false}
if(!/^[a-zA-Z][a-zA-Z0-9_]*$/.test(v)){showError('usernameErr','Use only letters, numbers, and underscores.');setInvalid('username',true);return false}
showError('usernameErr','');setInvalid('username',false);return true}

function validateEmail(){
var raw=document.getElementById('email').value;
var v=raw.trim();
if(!v){showError('emailErr','Email is required.');setInvalid('email',true);return false}
if(/\s/.test(v)){showError('emailErr','Email must not contain spaces.');setInvalid('email',true);return false}
var atCount=(v.match(/@/g)||[]).length;
if(atCount!==1){showError('emailErr','Enter a valid email address.');setInvalid('email',true);return false}
var parts=v.split('@');
var local=parts[0],domain=parts[1];
if(!local){showError('emailErr','Enter a valid email address.');setInvalid('email',true);return false}
if(local[0]==='.'||local[local.length-1]==='.'){showError('emailErr','Enter a valid email address.');setInvalid('email',true);return false}
if(local.indexOf('..')!==-1){showError('emailErr','Enter a valid email address.');setInvalid('email',true);return false}
if(!domain){showError('emailErr','Enter a valid email address.');setInvalid('email',true);return false}
var labels=domain.split('.');
if(labels.length<2){showError('emailErr','Enter a valid email address.');setInvalid('email',true);return false}
for(var i=0;i<labels.length;i++){
if(!labels[i]){showError('emailErr','Enter a valid email address.');setInvalid('email',true);return false}
if(labels[i][0]==='-'||labels[i][labels[i].length-1]==='-'){showError('emailErr','Enter a valid email address.');setInvalid('email',true);return false}
}
showError('emailErr','');setInvalid('email',false);return true}

function validateDob(){
var v=document.getElementById('dob').value;
if(!v){showError('dobErr','');clearInvalid('dob');return true}
if(!/^\d{4}-\d{2}-\d{2}$/.test(v)){showError('dobErr','Enter a valid date (YYYY-MM-DD).');setInvalid('dob',true);return false}
var d=new Date(v+'T00:00:00');
if(isNaN(d.getTime())){showError('dobErr','Enter a valid date.');setInvalid('dob',true);return false}
var now=new Date();
if(d>now){showError('dobErr','Date of birth cannot be in the future.');setInvalid('dob',true);return false}
var minDate=new Date('1900-01-01T00:00:00');
if(d<minDate){showError('dobErr','Enter a date after 1900.');setInvalid('dob',true);return false}
showError('dobErr','');setInvalid('dob',false);return true}

function passwordStrength(v){
var s=0;if(v.length>=10)s++;if(v.length>=14)s++;if(/[a-z]/.test(v)&&/[A-Z]/.test(v))s++;if(/\d/.test(v))s++;if(/[^a-zA-Z0-9]/.test(v))s++;return s}

function validatePassword(){
var v=document.getElementById('password').value;
var stEl=document.getElementById('pwStrength');
if(!v){showError('passwordErr','Password is required.');setInvalid('password',true);stEl.textContent='';return false}
if(v.length<10){showError('passwordErr','Password must be at least 10 characters.');setInvalid('password',true);stEl.textContent='';return false}
if(v.length>64){showError('passwordErr','Password must be 64 characters or fewer.');setInvalid('password',true);stEl.textContent='';return false}
if(!/[a-zA-Z]/.test(v)){showError('passwordErr','Password must contain at least one letter.');setInvalid('password',true);stEl.textContent='';return false}
if(!/\d/.test(v)){showError('passwordErr','Password must contain at least one digit.');setInvalid('password',true);stEl.textContent='';return false}
showError('passwordErr','');setInvalid('password',false);
var s=passwordStrength(v);
stEl.className='pw-strength';
if(s<=2){stEl.classList.add('weak');stEl.textContent='Weak password — add length, mixed case, numbers, and symbols.'}
else if(s<=3){stEl.classList.add('fair');stEl.textContent='Fair password strength.'}
else{stEl.classList.add('strong');stEl.textContent='Strong password.'}
return true}

function validateConfirm(){
var v=document.getElementById('confirmPassword').value;
var p=document.getElementById('password').value;
if(!v){showError('confirmErr','Please confirm your password.');setInvalid('confirmPassword',true);return false}
if(v!==p){showError('confirmErr','Passwords do not match.');setInvalid('confirmPassword',true);return false}
showError('confirmErr','');setInvalid('confirmPassword',false);return true}

function validateTerms(){
var c=document.getElementById('terms').checked;
if(!c){showError('termsErr','You must accept the Terms of Service.');return false}
showError('termsErr','');return true}

function checkDuplicate(username,email){
var users=getUsers();
var unLower=username.toLowerCase();
var emLower=email.toLowerCase();
return users.some(function(u){return u.username.toLowerCase()===unLower||u.email.toLowerCase()===emLower})}

form.addEventListener('submit',function(e){
e.preventDefault();
successBanner.classList.remove('show');
hideSummary();
var results={
username:validateUsername(),
email:validateEmail(),
dob:validateDob(),
password:validatePassword(),
confirm:validateConfirm(),
terms:validateTerms()
};
var allValid=results.username&&results.email&&results.dob&&results.password&&results.confirm&&results.terms;
if(!allValid){
var msgs=[];
if(!results.username)msgs.push('username');
if(!results.email)msgs.push('email');
if(!results.dob)msgs.push('date of birth');
if(!results.password)msgs.push('password');
if(!results.confirm)msgs.push('password confirmation');
if(!results.terms)msgs.push('terms acceptance');
showSummary('Please correct the following errors: '+msgs.join(', ')+'.');
var order=['username','email','dob','password','confirmPassword','terms'];
var firstInvalid=null;
for(var i=0;i<order.length;i++){
var id=order[i];
var el=document.getElementById(id);
if(el.getAttribute('aria-invalid')==='true'){firstInvalid=el;break}
}
if(firstInvalid)firstInvalid.focus();
return;
}
var username=document.getElementById('username').value.trim();
var email=document.getElementById('email').value.trim().toLowerCase();
if(checkDuplicate(username,email)){
showError('usernameErr','This username is already registered.');
setInvalid('username',true);
showError('emailErr','This email is already registered.');
setInvalid('email',true);
showSummary('An account with this username or email already exists. Please use different details or log in.');
document.getElementById('username').focus();
return;
}
var dob=document.getElementById('dob').value;
var users=getUsers();
users.push({username:username,email:email,dob:dob||null,createdAt:new Date().toISOString()});
saveUsers(users);
form.reset();
document.querySelectorAll('[aria-invalid]').forEach(function(el){el.removeAttribute('aria-invalid')});
document.getElementById('pwStrength').textContent='';
hideSummary();
successBanner.textContent='Registration successful! Welcome, '+username+'. You can now sign in.';
successBanner.classList.add('show');
successBanner.focus();
});

['username','email','dob','password','confirmPassword'].forEach(function(id){
var el=document.getElementById(id);
el.addEventListener('blur',function(){
if(id==='username')validateUsername();
else if(id==='email')validateEmail();
else if(id==='dob')validateDob();
else if(id==='password')validatePassword();
else if(id==='confirmPassword')validateConfirm();
});
el.addEventListener('input',function(){
var errId=id+'Err';
showError(errId,'');
clearInvalid(id);
if(id==='password'){
var v=this.value;
var stEl=document.getElementById('pwStrength');
if(v){
var s=passwordStrength(v);
stEl.className='pw-strength';
if(s<=2){stEl.classList.add('weak');stEl.textContent='Weak'}
else if(s<=3){stEl.classList.add('fair');stEl.textContent='Fair'}
else{stEl.classList.add('strong');stEl.textContent='Strong'}
}else{stEl.textContent=''}
}
});
});
document.getElementById('terms').addEventListener('change',validateTerms);

var pwToggle=document.getElementById('pwToggle');
var passwordInput=document.getElementById('password');
var confirmInput=document.getElementById('confirmPassword');
pwToggle.addEventListener('click',function(){
var isPw=passwordInput.type==='password';
passwordInput.type=isPw?'text':'password';
confirmInput.type=isPw?'text':'password';
pwToggle.textContent=isPw?'Hide':'Show';
pwToggle.setAttribute('aria-label',isPw?'Hide password':'Show password');
});
})();
</script>
</body>
</html>"}

